with lines as (select id, customer_id, created_at, coupon_codes, elem.product_id, elem.qty, elem.price, elem.promo from carts lateral view explode(items) e as elem) select customer_id, created_at, coupon_codes, price, promo, case when promo rlike '^(BUNDLE|VIP)$' then 'GROUP_A' when promo rlike '^(SPRING10|WELCOME5)$' then 'EXTENDED' else 'CORE' end as promo_zone from lines order by promo desc nulls last, created_at
